import{_ as i,c as t,o as a,ag as r}from"./chunks/framework.Dj4VfQLU.js";const m=JSON.parse('{"title":"Perquisites","description":"","frontmatter":{"icon":"exclamation"},"headers":[],"relativePath":"perquisites.md","filePath":"perquisites.md"}'),o={name:"perquisites.md"};function n(s,e,l,u,d,c){return a(),t("div",null,e[0]||(e[0]=[r('<h1 id="perquisites" tabindex="-1">Perquisites <a class="header-anchor" href="#perquisites" aria-label="Permalink to &quot;Perquisites&quot;">​</a></h1><p>Before installing and deploying Ridy, ensure the following prerequisites are met to avoid errors during setup and to ensure a fully functional, secure environment.</p><h4 id="📦-code-access" tabindex="-1">📦 Code Access <a class="header-anchor" href="#📦-code-access" aria-label="Permalink to &quot;📦 Code Access&quot;">​</a></h4><ul><li>The full source code is provided as a downloadable ZIP archive.</li><li><strong>No need to install Git</strong> or manage repositories.</li></ul><h4 id="💻-server-requirements" tabindex="-1">💻 Server Requirements <a class="header-anchor" href="#💻-server-requirements" aria-label="Permalink to &quot;💻 Server Requirements&quot;">​</a></h4><ul><li>A VPS or cloud instance running <strong>Ubuntu 22.04 LTS</strong>.</li><li><strong>Static IP address</strong> (mandatory for license validation and SSL setup).</li><li>Root or sudo access to run installation scripts.</li></ul><h4 id="⚙️-installation-script" tabindex="-1">⚙️ Installation Script <a class="header-anchor" href="#⚙️-installation-script" aria-label="Permalink to &quot;⚙️ Installation Script&quot;">​</a></h4><ul><li>A <strong>one-line automated install script</strong> is provided.</li><li>This script: <ul><li>Installs <strong>Docker</strong> and <strong>Docker Compose</strong> (if not already installed)</li><li>Pulls and builds required containers</li><li>Starts all backend and admin services</li></ul></li></ul><blockquote><p>No need for manual dependency installation — everything runs in Docker containers.</p></blockquote><h4 id="🌐-domain-https" tabindex="-1">🌐 Domain &amp; HTTPS <a class="header-anchor" href="#🌐-domain-https" aria-label="Permalink to &quot;🌐 Domain &amp; HTTPS&quot;">​</a></h4><ul><li>A valid domain name or static IP is required.</li><li>HTTPS/SSL is <strong>not set up automatically</strong>. Manual configuration is needed. <ul><li><strong>Cloudflare</strong> reverse proxy setup is highly recommended for ease of SSL and caching.</li><li>Alternatively, self-hosted SSL (e.g., via Let’s Encrypt) can be configured post-deployment.</li></ul></li></ul><h4 id="📱-mobile-app-requirements" tabindex="-1">📱 Mobile App Requirements <a class="header-anchor" href="#📱-mobile-app-requirements" aria-label="Permalink to &quot;📱 Mobile App Requirements&quot;">​</a></h4><ul><li>Apps are provided <strong>in source code format</strong> and must be compiled locally.</li><li>Requirements: <ul><li><strong>Android SDK 21+</strong></li><li><strong>Flutter (stable channel)</strong></li><li><strong>Xcode</strong> (for iOS builds)</li></ul></li><li><strong>Firebase Setup Required</strong> for: <ul><li>Push notifications</li><li>App configuration</li></ul></li></ul><blockquote><p>Firebase keys must be set up in each app before compilation.</p></blockquote><h4 id="🔑-api-keys-configs" tabindex="-1">🔑 API Keys &amp; Configs <a class="header-anchor" href="#🔑-api-keys-configs" aria-label="Permalink to &quot;🔑 API Keys &amp; Configs&quot;">​</a></h4><ul><li>A preconfigured <code>.env.example</code> file is included to help with environment setup.</li><li><strong>Required configurations:</strong><ul><li><strong>Map Provider Keys</strong> (for Google Maps, Mapbox, MapLibre, etc.) — configured via <code>.env</code></li><li><strong>SMS &amp; Payment Gateway Keys</strong> — entered directly from the Admin Panel under their respective configuration pages</li></ul></li></ul>',16)]))}const g=i(o,[["render",n]]);export{m as __pageData,g as default};
